<script lang="ts">import {permissions,preset,presets,type Engine,type Preset} from '$lib/database/model';export let engine:Engine;export let initial:string[];export let onSave:(values:string[])=>void;export let onCancel:()=>void;let selected=[...initial];let error='';function choose(p:Preset){selected=preset(engine,p);}function save(){try{onSave(selected);error='';}catch(e){error=e instanceof Error?e.message:'Could not save privileges.';}}</script>
<div class="db5-privform stack"><div class="row between wrap"><strong>Privileges</strong><div class="row wrap">{#each presets as p}<button class="btn secondary small" type="button" on:click={()=>choose(p)}>{p}</button>{/each}<button class="btn secondary small" type="button" on:click={()=>selected=[]}>Clear all</button></div></div><div class="native-db-permissions">{#each permissions(engine) as permission}<label class="check"><input type="checkbox" bind:group={selected} value={permission}/> {permission}</label>{/each}</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="row wrap"><button class="btn primary" type="button" disabled={!selected.length} on:click={save}>Save Changes</button><button class="btn secondary" type="button" on:click={onCancel}>Cancel</button></div></div>
